const Tokenizer = (() => {
  const words = (list) => new Set(list.split(" ").filter((word) => word !== ""));
  const JsWords = "const let var function return if else for while do of in new class extends import export from default switch case break continue try catch finally throw typeof instanceof null undefined true false this async await yield delete void super";
  const TsWords = "type interface enum implements satisfies as is keyof readonly declare namespace abstract private public protected infer unique never unknown any boolean string number symbol bigint object asserts override";
  const SwiftWords = "actor any as associatedtype async await borrowing break case catch class consuming continue convenience copy default defer deinit didSet distributed do dynamic each else enum extension fallthrough false fileprivate final for func get guard if import indirect infix init in inout internal is isolated lazy let macro mutating nil nonisolated nonmutating open operator optional override package postfix precedencegroup prefix private protocol public repeat required rethrows return self Self sending set some static struct subscript super switch throw throws true try typealias unowned var weak where while willSet";
  const Identifier = /[A-Za-z_]\w*/y;
  const JsIdentifier = /[A-Za-z_$][\w$]*/y;
  const JsGrammar = { comment: "//", block: ["/*", "*/"], strings: ['"', "'", "`"], keywords: words(JsWords), identifier: JsIdentifier, identifiers: true, objectKeys: true };
  const TsGrammar = { ...JsGrammar, keywords: words(`${JsWords} ${TsWords}`) };
  const Grammars = {
    python: { comment: "#", hashAnywhere: true, strings: ['"""', "'''", '"', "'"], keywords: words("def class return if elif else for while in not and or is None True False import from as with try except finally raise lambda yield pass continue break assert del async await global nonlocal"), identifiers: true, prefixes: /[rRbBfFuU]{1,2}(?=["'])/y, types: words("dict list tuple set frozenset str int float bool bytes object") },
    js: JsGrammar,
    jsx: { ...JsGrammar, jsx: true },
    ts: TsGrammar,
    tsx: { ...TsGrammar, jsx: true },
    swift: { comment: "//", block: ["/*", "*/"], strings: ['"""', '"'], keywords: words(SwiftWords), identifiers: true, sigils: /[@#][A-Za-z_]\w*/y },
    shell: { comment: "#", strings: ['"', "'"], variables: true, heredocs: true, keywords: words("if then else elif fi for in do done while until case esac function return local export set exit trap source echo readonly shift") },
    yaml: { comment: "#", strings: ['"', "'"], keys: true, keywords: words("true false null") },
    html: { block: ["<!--", "-->"], strings: ['"', "'"], tags: true, keywords: words("") },
    css: { block: ["/*", "*/"], strings: ['"', "'"], css: true, keywords: words("") },
  };
  const LanguageByExtension = { py: "python", js: "js", mjs: "js", jsx: "jsx", ts: "ts", tsx: "tsx", swift: "swift", json: "js", sh: "shell", bash: "shell", yml: "yaml", yaml: "yaml", html: "html", css: "css" };

 */
const tokenAt = (cursor, grammar) => {
  const isYamlKeyPosition = grammar.keys === true && cursor.lineStart;
  const key = isYamlKeyPosition ? matchAt(YamlKey, cursor) : null;
  if (key) return Token("tok-key", key);
  const quoted = quotedAt(cursor, grammar);
  if (quoted) return quoted;
  const sigil = grammar.sigils === undefined ? null : matchAt(grammar.sigils, cursor);
  if (sigil) {
    return Token("tok-kw", sigil);
  }
  if (grammar.css === true) return cssTokenAt(cursor);
  const variable = grammar.variables === true ? matchAt(ShellVariable, cursor) : null;
  if (variable) return Token("tok-var", variable);
  const jsx = grammar.jsx === true ? jsxTagInExpressionAt(cursor) : null;
  if (jsx) return jsx;
  return wordAt(cursor, grammar);
};

/** 持ち越しの続き(前の行で閉じなかった文字列・コメント)を、閉じ記号まで 1 字句にする。 */

  create: (excerpt) => {
    const emphasis = listOf(excerpt.emphasis);
    const grammar = Tokenizer.grammarOf(excerpt.path);
    const texts = excerpt.text.split("\n");
    const read = Tokenizer.tokenizeLines(texts, grammar, Tokenizer.startAfter(isString(excerpt.openingLine) ? excerpt.openingLine : null, grammar));
    return texts.map((text, index) => {
      const number = excerpt.start + index;
      return { number, text, isEmphasized: emphasis.some((span) => isWithin(number, span)), tokens: read[index].tokens };
    });
  },
});

